  var lab = behaviors.map(function(b){ return measure(b); }), wMax = Math.max.apply(null, lab.map(function(b){ return b.width; }));
  var e1 = measure("Emergency", C.bad), e2 = measure("stop", C.bad), lh = e1.height;
  var padX = 12, boxW = wMax + 2 * padX, boxH = lh + 12, eW = Math.max(e1.width, e2.width) + 2 * padX, eH = 2 * lh + 14;
  var top = superstate ? lh + 22 : 10, gap = Math.max(6, (H - top - 10 - 5 * boxH - (superstate ? 10 : 0)) / 4);
  var x0 = superstate ? 22 : 8, ex = W - eW - 6, ey = H / 2 - eH / 2;
  if (superstate){ el(s,"rect",{x:6,y:6,width:boxW + 32,height:H - 12,rx:16,fill:C.planFill,stroke:C.plan,"stroke-width":2.5});
    txt(s, x0 + boxW / 2, 6 + lh + 4, "Driving", 17, C.plan, "middle", {"font-weight":600}); }
  behaviors.forEach(function(b, i){ var y = top + i * (boxH + gap);
    el(s,"rect",{x:x0,y:y,width:boxW,height:boxH,rx:6,fill:"#fff",stroke:C.slate,"stroke-width":1.5});
    el(s,"text",{x:x0 + boxW / 2, y:y + boxH / 2, "text-anchor":"middle", "dominant-baseline":"central", "font-size":lab[i].height ? null : 15, fill:C.ink, "font-family":FONT}, b).setAttribute("font-size", txt(s, 0, -100, "x", 15).getAttribute("font-size"));
    if (!superstate){ var x1 = x0 + boxW, mx = (x1 + ex) / 2; el(s,"path",{d:"M"+x1+","+(y+boxH/2)+" C"+mx+","+(y+boxH/2)+" "+mx+","+(H/2)+" "+(ex-2)+","+(H/2),fill:"none",stroke:C.live,"stroke-width":2.2,"marker-end":"url(#fa)"}); } });
  [].slice.call(s.querySelectorAll("text")).forEach(function(n){ if (+n.getAttribute("y") === -100) n.remove(); });
  el(s,"rect",{x:ex,y:ey,width:eW,height:eH,rx:6,fill:"#fff",stroke:C.bad,"stroke-width":2});
  [["Emergency", ey + 7 + lh / 2], ["stop", ey + 7 + lh * 1.5]].forEach(function(r){
    var n = txt(s, ex + eW / 2, r[1], r[0], 15, C.bad); n.setAttribute("dominant-baseline", "central"); });
  if (superstate) el(s,"path",{d:"M"+(boxW + 38)+","+(H/2)+" L"+(ex-2)+","+(H/2),fill:"none",stroke:C.live,"stroke-width":3,"marker-end":"url(#fa)"});
