  function interp(arr, s){ if (s <= ref.s[0]) return arr[0]; if (s >= ref.s[n-1]) return arr[n-1];
    var lo = 0, hi = n - 1; while (hi - lo > 1){ var m = (lo + hi) >> 1; if (ref.s[m] <= s) lo = m; else hi = m; }
    var f = (s - ref.s[lo]) / (ref.s[hi] - ref.s[lo]); return arr[lo] + f * (arr[hi] - arr[lo]); }
