    ts.forEach(function(t){ var tt = Math.min(t, T), p = pv(c, tt), v = pv(c1, tt), a = pv(c2, tt), j = pv(c3, tt);
      if (t > T){ p += v * (t - T); a = 0; j = 0; } out.p.push(p); out.v.push(v); out.a.push(a); out.j.push(j); });
