  function jerkCost(c, T){ var c3 = der(der(der(c))), N = 400, h = T / N, s = 0;
    for (var i = 0; i <= N; i++){ var j = pv(c3, i * h), w = (i === 0 || i === N) ? 0.5 : 1; s += w * j * j; } return s * h; }
