    var s0 = sc.av_s, sd0 = sc.av_v, sdd0 = 0, d0 = sc.av_d, lane = targetLane(s0, sc);
    var parked = carCircles(sc.car_s, sc.car_d), bAt = TS.map(function(t){ return carCircles(sc.b_s + sc.b_v * t, sc.b_d); });
