      var vx = grad(x, DT), vy = grad(y, DT), ax = grad(vx, DT), ay = grad(vy, DT), aSide = 0;
      for (k = 0; k < TS.length; k++) aSide = Math.max(aSide, Math.abs(vx[k] * ay[k] - vy[k] * ax[k]) / Math.max(Math.hypot(vx[k], vy[k]), 1e-3));
