      [-1.75, 5.25].forEach(function(d){ el(s,"line",{x1:X(S0),y1:Y(d),x2:X(S1),y2:Y(d),stroke:"#5B6B7C","stroke-width":2}); });
      el(s,"line",{x1:X(S0),y1:Y(1.75),x2:X(S1),y2:Y(1.75),stroke:"#5B6B7C","stroke-width":1.5,"stroke-dasharray":"10 8"});
