      var dfs = Math.max(14, TXT_MIN / svgScale(s));
      for (var m = 40; m <= 180; m += 20){ el(s,"line",{x1:X(m),y1:Y(-1.75),x2:X(m),y2:Y(-1.75) + 3,stroke:"#5B6B7C"}); txt(s, X(m), Y(-1.75) + 5 + 0.93 * dfs, "s = " + m + " m", 14, "#5B6B7C"); }
