      r.b.forEach(function(b, j){ txt(g, 14, r.y + 50 + 25 * j, b, 21, C.ink, "start", {opacity:op}); });
      arrow(BOXW + 4, cy(i), NX - 2, cy(i), on && dim ? C.follow : C.muted, on && dim ? 3 : 2, op);
